<?php

namespace App\Reports;

use App\Models\Admin;
use PhpOffice\PhpSpreadsheet\Cell\Coordinate;
use PhpOffice\PhpSpreadsheet\Cell\DataType;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Style\Fill;
use PhpOffice\PhpSpreadsheet\Style\NumberFormat;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
use Symfony\Component\HttpFoundation\StreamedResponse;

/**
 * Writes a report to CSV or XLSX with the spec's file header (D-112): Report
 * Name, Generated At, Generated By, Filters Applied and Language; then one
 * heading row and the data. No totals
 * row: it would break filtering and re-import (spec, open question 11).
 *
 * Text cells that start like a formula are written as text (XLSX) or with a
 * leading apostrophe (CSV), so a learner-typed value can never run as a
 * formula in the reader's spreadsheet (CSV injection).
 */
final class ReportExporter
{
    public const FORMATS = ['xlsx', 'csv'];

    /** Rows a synchronous export may hold (measured, see D-112). */
    public const MAX_ROWS = 10000;

    private const CHUNK = 1000;

    public function __construct(private readonly ReportOptions $options) {}

    /**
     * @return array<int, array{0: string, 1: string}>  label => value lines of the file header
     */
    public function header(Report $report, ReportContext $context, ?Admin $admin): array
    {
        $lines = [
            [__('reports.header.report_name'), $report->name()],
            [__('reports.header.generated_at'), now()->format('Y-m-d H:i')],
            [__('reports.header.generated_by'), $admin?->getLocalizedName($context->locale) ?? ''],
            [__('reports.header.filters_applied'), $this->describeFilters($report, $context)],
            [__('reports.header.language'), __("reports.languages.{$context->locale}")],
        ];

        return $lines;
    }

    public function describeFilters(Report $report, ReportContext $context): string
    {
        $parts = [];
        foreach ($report->filters() as $filter) {
            $value = match ($filter->type) {
                Filter::MULTI => implode(', ', $this->options->labels(
                    (string) $filter->source,
                    $filter->usesStrings() ? $context->strings($filter->key) : $context->ids($filter->key),
                    $context,
                )),
                Filter::SELECT => $context->id($filter->key) === null ? ''
                    : implode(', ', $this->options->labels((string) $filter->source, [$context->id($filter->key)], $context)),
                Filter::STATUS => implode(', ', array_map(fn (string $v) => __($filter->options[$v]), $context->strings($filter->key))),
                Filter::DATE_RANGE => trim(($context->filters["{$filter->key}_from"] ?? '').' - '.($context->filters["{$filter->key}_to"] ?? ''), ' -'),
                Filter::DATE => (string) ($context->filters[$filter->key] ?? ''),
                Filter::NUMBER => $context->number($filter->key) === null ? '' : $context->number($filter->key).'%',
            };
            if ($value !== '') {
                $parts[] = $filter->label().' = '.$value;
            }
        }
        if ($context->search !== null && $context->search !== '') {
            $parts[] = __('reports.filters.search').' = '.$context->search;
        }

        return $parts === [] ? __('reports.header.no_filters') : implode('; ', $parts);
    }

    public function filename(Report $report, string $format): string
    {
        return 'NAS-'.$report->key().'-'.now()->format('Y-m-d-His').'.'.$format;
    }

    public function csv(Report $report, ReportContext $context, ?Admin $admin): StreamedResponse
    {
        return response()->streamDownload(function () use ($report, $context, $admin) {
            $this->writeCsv($report, $context, $admin, 'php://output');
        }, $this->filename($report, 'csv'), ['Content-Type' => 'text/csv; charset=UTF-8']);
    }

    public function xlsx(Report $report, ReportContext $context, ?Admin $admin): StreamedResponse
    {
        $book = $this->spreadsheet($report, $context, $admin);

        return response()->streamDownload(function () use ($book) {
            (new Xlsx($book))->save('php://output');
            $book->disconnectWorksheets();
        }, $this->filename($report, 'xlsx'), ['Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
    }

    /** Write the report to `$path` in `$format` (the Export All zip). */
    public function writeFile(Report $report, ReportContext $context, ?Admin $admin, string $format, string $path): void
    {
        if ($format === 'csv') {
            $this->writeCsv($report, $context, $admin, $path);

            return;
        }
        $book = $this->spreadsheet($report, $context, $admin);
        (new Xlsx($book))->save($path);
        $book->disconnectWorksheets();
    }

    private function writeCsv(Report $report, ReportContext $context, ?Admin $admin, string $target): void
    {
        $columns = $report->columns($context);
        $out = fopen($target, 'wb');
        fwrite($out, "\xEF\xBB\xBF");
        foreach ($this->header($report, $context, $admin) as $line) {
            fputcsv($out, array_map([self::class, 'csvSafe'], $line));
        }
        fputcsv($out, []);
        fputcsv($out, array_map(fn (Column $c) => self::csvSafe($c->label()), $columns));
        foreach ($report->chunks($context, self::CHUNK) as $chunk) {
            foreach ($chunk as $row) {
                fputcsv($out, array_map(fn (Column $c) => $this->csvValue($c, $row[$c->key] ?? null), $columns));
            }
        }
        fclose($out);
    }

    private function spreadsheet(Report $report, ReportContext $context, ?Admin $admin): Spreadsheet
    {
        $columns = $report->columns($context);
        $book = new Spreadsheet();
        $sheet = $book->getActiveSheet();
        // Excel refuses these characters in a sheet name, and more than 31 of them.
        $sheet->setTitle(mb_substr(str_replace(['\\', '/', '?', '*', '[', ']', ':'], ' ', $report->name()), 0, 31));
        $sheet->setRightToLeft($context->isArabic());

        $r = 1;
        foreach ($this->header($report, $context, $admin) as [$label, $value]) {
            $sheet->setCellValueExplicit([1, $r], $label, DataType::TYPE_STRING);
            $sheet->setCellValueExplicit([2, $r], $value, DataType::TYPE_STRING);
            $sheet->getStyle([1, $r])->getFont()->setBold(true);
            $r++;
        }
        $r++;

        $headingRow = $r;
        foreach ($columns as $i => $column) {
            $sheet->setCellValueExplicit([$i + 1, $r], $column->label(), DataType::TYPE_STRING);
        }
        $last = Coordinate::stringFromColumnIndex(max(1, count($columns)));
        $sheet->getStyle("A{$r}:{$last}{$r}")->getFont()->setBold(true);
        $sheet->getStyle("A{$r}:{$last}{$r}")->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('FFF5F5F5');
        $sheet->freezePane('A'.($r + 1));

        foreach ($report->chunks($context, self::CHUNK) as $chunk) {
            foreach ($chunk as $row) {
                $r++;
                foreach ($columns as $i => $column) {
                    $this->xlsxCell($sheet, $i + 1, $r, $column, $row[$column->key] ?? null);
                }
            }
        }
        if ($r > $headingRow) {
            $sheet->setAutoFilter("A{$headingRow}:{$last}{$r}");
        }
        foreach (range(1, count($columns)) as $i) {
            $sheet->getColumnDimensionByColumn($i)->setWidth(22);
        }

        return $book;
    }

    private function xlsxCell(\PhpOffice\PhpSpreadsheet\Worksheet\Worksheet $sheet, int $col, int $row, Column $column, mixed $value): void
    {
        if ($value === null) {
            return;
        }
        match ($column->type) {
            Column::NUMBER => $sheet->setCellValueExplicit([$col, $row], (float) $value, DataType::TYPE_NUMERIC),
            Column::PERCENT => (function () use ($sheet, $col, $row, $value) {
                $sheet->setCellValueExplicit([$col, $row], round((float) $value / 100, 4), DataType::TYPE_NUMERIC);
                $sheet->getStyle([$col, $row])->getNumberFormat()->setFormatCode('0.0%');
            })(),
            Column::YES_NO => $sheet->setCellValueExplicit([$col, $row], self::yesNo((bool) $value), DataType::TYPE_STRING),
            default => is_int($value) || is_float($value)
                ? $sheet->setCellValueExplicit([$col, $row], $value, DataType::TYPE_NUMERIC)
                : $sheet->setCellValueExplicit([$col, $row], (string) $value, DataType::TYPE_STRING),
        };
        if ($column->type === Column::NUMBER && fmod((float) $value, 1.0) !== 0.0) {
            $sheet->getStyle([$col, $row])->getNumberFormat()->setFormatCode(NumberFormat::FORMAT_NUMBER_00);
        }
    }

    private function csvValue(Column $column, mixed $value): string
    {
        if ($value === null) {
            return '';
        }

        return match ($column->type) {
            Column::PERCENT => rtrim(rtrim(number_format((float) $value, 1, '.', ''), '0'), '.').'%',
            Column::YES_NO => self::yesNo((bool) $value),
            Column::NUMBER => (string) ((float) $value + 0),
            default => self::csvSafe((string) $value),
        };
    }

    private static function yesNo(bool $value): string
    {
        return __($value ? 'reports.values.yes' : 'reports.values.no');
    }

    /** A text value that starts like a formula is prefixed so it stays text. */
    public static function csvSafe(string $value): string
    {
        return $value !== '' && in_array($value[0], ['=', '+', '-', '@', "\t", "\r"], true) ? "'".$value : $value;
    }
}
